  phd03: { steps: ['整理课程成绩、科研经历、代码、报告和英语使用情况。', '为每段经历写明个人贡献、合作人员、成果状态和可公开证据。'], outcome: '一份事实材料库，以及申请前最需要补齐的缺口。', pitfall: '把在投论文写成已录用，或把共同成果全部归于自己。', resources: ['academic', 'orcid'] },
  phd04: { steps: ['先看目标项目官方页：是统一招生、项目招聘还是其他方式。', '分别记录学位资格、导师联系要求、申请入口和资助申请流程。'], outcome: '每个目标都有自己的申请机制说明和官方来源。', pitfall: '按国家套用统一规则；同一地区的学校和项目也可能不同。', resources: ['gradweb', 'euraxess', 'yz'] },
  phd05: { steps: ['从研究关键词检索实验室，再查看院系和研究生院页面。', '记录研究匹配、潜在导师、申请入口及仍待核实的条件。'], outcome: '一份有具体匹配理由的长名单，再筛成可认真准备的目标。', pitfall: '只按排名分档，忽略研究主题和招生条件。', resources: ['csrankings', 'researchmap'] },
  phd06: { steps: ['阅读近期代表论文，关注方法、实验和持续研究的问题。', '区分导师本人主导方向、合作项目以及已经结束的课题。'], outcome: '每位候选导师至少有一段引用具体工作的匹配说明。', pitfall: '只看主页关键词，或用多年以前的论文判断当前方向。', resources: ['dblp', 'scholar', 'openreview'] },
  phd07: { steps: ['交叉核对院系名录、导师主页、实验室动态与招生说明。', '在允许的沟通范围内了解指导方式、资源、毕业生去向和招生计划。'], outcome: '导师状态、沟通结论与信息日期均有记录。', pitfall: '把未回复邮件当成拒绝，或把公开主页当作招生承诺。', resources: ['gradweb', 'researchmap'] },
  phd08: { steps: ['分别查学费、生活资助、年限、续期条件和申请资格。', '分清博士录取与奖学金是否需要两次申请，以及各自期限。'], outcome: '一张申请与资助要求表，未知项标记待确认。', pitfall: '看到“funded”就默认覆盖所有费用和全部学制。', resources: ['euraxess', 'findaphd', 'csc'] },
  phd09: { steps: ['按研究、论文、项目、教育和相关技能组织学术 CV。', '标明论文状态、作者信息和个人贡献，核对公开代码及主页链接。'], outcome: 'CV、成果链接与事实材料库互相一致。', pitfall: '使用含糊论文状态，或把尚未公开的合作成果直接上传。', resources: ['overleaf', 'academic', 'orcid'] },
  phd10: { steps: ['先读目标项目的文书题目、篇幅和格式要求。', '用具体研究经历说明问题、贡献、结果、局限及与目标团队的联系。'], outcome: '每个目标均有回答其文书问题的独立版本。', pitfall: '用学校赞美和个人口号替代科研证据，或混用 SOP 与研究计划。', resources: ['phdcsus', 'csgradapps'] },
  phd11: { steps: ['逐个项目核对成绩单格式、翻译、考试要求及推荐信规则。', '记录上传或送分方式、材料有效期及收件状态。'], outcome: '每个目标都有逐项材料清单，附官网要求及查询日期。', pitfall: '默认所有项目要求相同，或只提交表单却未确认材料到齐。', resources: ['gradweb'] },
  phd12: { steps: ['联系能具体评价你工作的推荐人，说明目标、时间和提交方式。', '提供 CV、成绩、共同工作事实、目标清单和文书草稿。'], outcome: '推荐人确认意愿，并掌握各目标要求及期限。', pitfall: '只追求推荐人的名气，或要求对方签署失实内容。', resources: ['csgradapps'] },
  phd13: { steps: ['打开目标院系和申请系统，核对批次、日期、具体时间与时区。', '同时检查推荐信、考试成绩、奖学金等是否存在单独期限。'], outcome: '官方链接、完整截止时间及自己的提前提交安排已记录。', pitfall: '沿用往年日期，或把北京时间与官方当地时间混用。', resources: ['gradweb'] },
  phd14: { steps: ['先核实项目是否欢迎或要求提前联系。', '如适合联系，引用具体论文并介绍相关经历，提出一个明确问题。'], outcome: '有针对性的邮件草稿或无需联系的官方说明已留档。', pitfall: '群发模板、反复催促，或把积极回复当作正式录取。', resources: ['phdcsus', 'gradweb'] },
  phd15: { steps: ['按官方清单核对姓名、项目名、文书题目、附件与成果状态。', '预览最终文件并检查推荐人状态；提交后保存回执和最终版本。'], outcome: '有提交回执，且所有待补材料都有跟进安排。', pitfall: '只修改文件名，文书里仍保留另一所学校或导师姓名。', resources: ['gradweb'] },
  phd16: { steps: ['在看板记录状态、下一步、联系人及回复要点。', '面试准备研究讲解、方法细节、失败经验与希望了解的问题。'], outcome: '申请和沟通记录可追溯，补件或面试事项有清晰负责人和日期。', pitfall: '只查邮箱，忘记申请系统中的补件通知。', resources: ['gradweb'] },
  phd17: { steps: ['通过正式访谈或自愿交流了解指导频率、合作方式和学生支持。', '把实际信息与自己的工作习惯、研究目标和所需支持对照。'], outcome: '每个团队的适配理由和仍需询问的问题均可说明。', pitfall: '只凭单一传闻下结论，或把个别经历当作整个团队的常态。', resources: [] },
  phd18: { steps: ['阅读正式资助文件，分别核对学费、生活资助、保险和期限。', '确认续期、助教或助研职责以及尚未写明的条件。'], outcome: '有可核查的书面资助说明及未决问题清单。', pitfall: '把非正式估计当作保证，或忽略附带职责和续期条件。', resources: ['csc', 'gradweb'] },
  phd19: { steps: ['查学校官方毕业手册、住宿信息和适用的入境官方说明。', '把生活安排、研究目标、毕业要求与个人长期计划并排比较。'], outcome: '一份有来源的可行性清单，重要未知项已提出确认。', pitfall: '直接照搬他人办理经历，或默认毕业时间和未来去向有保证。', resources: ['gradweb'] },
  phd20: { steps: ['核对正式录取与资助文件、接受期限及前置条件。', '提出最后的澄清问题，按自己的优先级决定并保存往来记录。'], outcome: '能解释选择理由，接受方式和后续办理事项均已确认。', pitfall: '在关键条件未写清前，把口头意向当作确定结果。', resources: [] }
